    TEST_ASSERT_EQUAL(0, GPIO_SetDir(gpio_A, CSK_GPIO_PIN0, CSK_GPIO_DIR_OUTPUT));
    
    // 仅测试写操作是否成功，不测试回读值（平台不支持回读）
